class ConstMember {
    const int N;
    int& R;
    int value = 100;

public:
    // Required for const/references
    ConstMember(int n, int& ref)
        : N(n), R(ref)
    {
        // N and R cannot be assigned here
    }
};

class Base {
    int id;
public:
    Base(int i) : id(i) {}
};

class Derived : public Base {
    int count;
public:
    // Initializes Base subobject first
    Derived(int i, int c)
        : Base(i), count(c) {}
};

// Initialization Order:
// 1. Base classes (in declaration order)
// 2. Member variables (in declaration order)
// ... NOT in list order
